SELECT stddev(count_procedures) AS standard_deviation FROM (SELECT p.subject_id, COUNT(DISTINCT pr.procedure_id) AS count_procedures FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN procedures_icd pr ON a.hadm_id = pr.subject_id AND a.stay_id = pr.hadm_id WHERE p.gender = 'M' AND p.anchor_year = 1991 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 1986 AND 1996 AND (pr.icd_code like '47%' OR pr.icd_code like '48%') GROUP BY p.subject_id) AS subquery;